function brIcons(root = document) {
  for (const el of root.querySelectorAll('[data-icon]')) {
    const markup = window.BR_ICONS[el.dataset.icon];
    if (markup) el.innerHTML = markup;
  }
}
document.addEventListener('DOMContentLoaded', () => brIcons());
